import PaginatedListState from 'flarum/common/states/PaginatedListState';

/**
 * `incoming` and `outgoing` are one row per other discussion, grouped the way
 * the sidebar preview is; `target` is every row pointing at one post.
 */

export default class ReferenceListState extends PaginatedListState {
  constructor(params, page) {
    if (page === void 0) {
      page = 1;
    }
    const limit = 20;
    params.page = {
      ...(params.page || {}),
      limit
    };
    super(params, page, limit);
  }
  get type() {
    return 'post-references';
  }

  /**
   * What is still there. A row deleted from the list stays in its page until
   * the next load, and a removed model is the one thing that would draw wrong.
   */
  references() {
    return this.getPages().flatMap(page => page.items).filter(reference => reference.exists);
  }
}
flarum.reg.add('datlechin-references', 'forum/states/ReferenceListState', ReferenceListState);