import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LinksModal from './LinksModal';
import { relationBadge } from '../utils/relations';
/**
 * The sidebar block: discussions that link here, and discussions this one
 * links to. Titles only. Dates, authors, notes, the map and moderation are in
 * LinksModal, so the sidebar stays short.
 *
 * On a phone the sidebar is a row of buttons above the first post, so the
 * block shrinks to one button there.
 */
export default class DiscussionLinks extends Component {
  view() {
    const discussion = this.attrs.discussion;
    const incoming = this.rows(discussion.referencedBy(), 'incoming');
    const outgoing = this.rows(discussion.outgoingReferences(), 'outgoing');
    if (!incoming.length && !outgoing.length) return null;
    const incomingCount = discussion.referencedByCount() ?? incoming.length;
    const outgoingCount = discussion.outgoingReferencesCount() ?? outgoing.length;
    const firstTab = incoming.length ? 'incoming' : 'outgoing';
    return m("div", {
      className: "DiscussionLinks"
    }, m(Button, {
      className: "Button DiscussionLinks-summary",
      icon: "fas fa-link",
      onclick: () => this.open(firstTab)
    }, app.translator.trans('datlechin-references.forum.links.summary_button', {
      count: incomingCount + outgoingCount
    })), m("div", {
      className: "DiscussionLinks-body"
    }, incoming.length > 0 && this.section('incoming', incoming, incomingCount), outgoing.length > 0 && this.section('outgoing', outgoing, outgoingCount), m(Button, {
      className: "Button Button--link DiscussionLinks-all",
      onclick: () => this.open(firstTab)
    }, app.translator.trans('datlechin-references.forum.links.all_button'))));
  }
  section(direction, references, count) {
    return m("section", {
      className: "DiscussionLinks-section"
    }, m("h4", {
      className: "DiscussionLinks-heading"
    }, app.translator.trans(`datlechin-references.forum.links.${direction}_heading`), m("span", {
      className: "DiscussionLinks-count"
    }, count)), m("ul", {
      className: "DiscussionLinks-list"
    }, references.map(reference => {
      const other = direction === 'incoming' ? reference.sourceDiscussion() : reference.targetDiscussion();
      const post = direction === 'incoming' ? reference.sourcePost() || null : null;
      return m("li", {
        key: reference.id()
      }, m(Link, {
        className: "DiscussionLinks-item",
        href: post ? app.route.discussion(other, post.number()) : app.route.discussion(other)
      }, other.title()), relationBadge(reference));
    })));
  }

  /**
   * One row per other discussion, already grouped by the server. Rows whose
   * other end is missing, or is this discussion, are skipped in case an old
   * payload is still cached.
   */
  rows(references, direction) {
    const seen = new Set([String(this.attrs.discussion.id())]);
    const rows = [];
    for (const reference of references || []) {
      if (!reference || !reference.exists) continue;
      const other = direction === 'incoming' ? reference.sourceDiscussion() : reference.targetDiscussion();
      const id = other ? String(other.id()) : null;
      if (!id || seen.has(id)) continue;
      seen.add(id);
      rows.push(reference);
    }
    return rows;
  }
  open(tab) {
    app.modal.show(LinksModal, {
      discussion: this.attrs.discussion,
      tab
    });
  }
}
flarum.reg.add('datlechin-references', 'forum/components/DiscussionLinks', DiscussionLinks);